import { expect, test, type Page } from '@playwright/test'

// A 400x300 PNG generated by a canvas in the page (a user action in the page's
// own world), so the test makes no network request and mutates no page or
// storage state beyond that canvas.
async function png400x300(page: Page): Promise<Buffer> {
  const buf = await page.evaluate(async () => {
    const canvas = document.createElement('canvas')
    canvas.width = 400
    canvas.height = 300
    const ctx = canvas.getContext('2d')!
    ctx.fillStyle = '#123456'
    ctx.fillRect(0, 0, 400, 300)
    ctx.fillStyle = '#ABCDEF'
    ctx.fillRect(0, 0, 200, 150)
    ctx.fillStyle = '#00FF00'
    ctx.fillRect(200, 150, 200, 150)
    return Array.from(new Uint8Array(await new Promise<Uint8Array>((resolve, reject) => {
      canvas.toBlob((b) => (b ? b.arrayBuffer().then((a) => resolve(new Uint8Array(a))) : reject(new Error('toBlob failed'))), 'image/png')
    })))
  })
  return Buffer.from(buf)
}

async function loadImage(page: Page) {
  const [chooser] = await Promise.all([
    page.waitForEvent('filechooser'),
    page.getByRole('button', { name: 'Load image' }).click(),
  ])
  await chooser.setFiles({ name: 'sample.png', mimeType: 'image/png', buffer: await png400x300(page) })
}

test('[A1] the page shows the heading and the Load image button', async ({ page }) => {
  await page.goto('/')
  await expect(page.getByRole('heading', { name: 'Screenshot Annotator' })).toBeVisible()
  await expect(page.getByRole('button', { name: 'Load image' })).toBeVisible()
})

test('[A2] loading an image shows the status Loaded: sample.png', async ({ page }) => {
  await page.goto('/')
  await loadImage(page)
  await expect(page.getByText('Loaded: sample.png')).toBeVisible()
})

test('[A3] Add text in the Tools tab adds a Label 1 text element to the canvas and the layer list', async ({ page }) => {
  await page.goto('/')
  await loadImage(page)
  await page.getByRole('tab', { name: 'Tools' }).click()
  await page.getByRole('button', { name: 'Add text' }).click()
  await expect(page.getByText('Label 1').first()).toBeVisible()
  await expect(page.getByText('Text: Label 1')).toBeVisible()
})

test('[A4] Rotate 90° in the Image tab changes the status to Rotated: 90°', async ({ page }) => {
  await page.goto('/')
  await loadImage(page)
  await page.getByRole('tab', { name: 'Image' }).click()
  await expect(page.getByRole('button', { name: 'Rotate 90°' })).toBeVisible()
  await page.getByRole('button', { name: 'Rotate 90°' }).click()
  await expect(page.getByText('Rotated: 90°')).toBeVisible()
})

test('[A5] Add rectangle in the Tools tab adds a shape element to the layer list', async ({ page }) => {
  await page.goto('/')
  await loadImage(page)
  await page.getByRole('tab', { name: 'Tools' }).click()
  await page.getByRole('button', { name: 'Add rectangle' }).click()
  await expect(page.getByText('Shape: Rectangle')).toBeVisible()
})

test('[A6] Flip horizontal in the Image tab changes the status to Flipped: horizontal', async ({ page }) => {
  await page.goto('/')
  await loadImage(page)
  await page.getByRole('tab', { name: 'Image' }).click()
  await page.getByRole('button', { name: 'Flip horizontal' }).click()
  await expect(page.getByText('Flipped: horizontal')).toBeVisible()
})

test('[A7] Export PNG triggers a download named annotated.png', async ({ page }) => {
  await page.goto('/')
  await loadImage(page)
  const [download] = await Promise.all([
    page.waitForEvent('download'),
    page.getByRole('button', { name: 'Export PNG' }).click(),
  ])
  expect(download.suggestedFilename()).toBe('annotated.png')
})

test('[A8] Delete last in the Tools tab removes the most recently added layer', async ({ page }) => {
  await page.goto('/')
  await loadImage(page)
  await page.getByRole('tab', { name: 'Tools' }).click()
  await page.getByRole('button', { name: 'Add text' }).click()
  await expect(page.getByText('Text: Label 1')).toBeVisible()
  await page.getByRole('button', { name: 'Add rectangle' }).click()
  await expect(page.getByText('Shape: Rectangle')).toBeVisible()
  await page.getByRole('button', { name: 'Delete last' }).click()
  await expect(page.getByText('Shape: Rectangle')).not.toBeVisible()
  await expect(page.getByText('Text: Label 1')).toBeVisible()
})

test('[A9] reloading keeps the layers and the loaded-image status', async ({ page }) => {
  await page.goto('/')
  await loadImage(page)
  await page.getByRole('tab', { name: 'Tools' }).click()
  await page.getByRole('button', { name: 'Add text' }).click()
  await page.getByRole('button', { name: 'Add rectangle' }).click()
  await page.reload()
  await expect(page.getByText('Loaded: sample.png')).toBeVisible()
  await expect(page.getByText('Text: Label 1')).toBeVisible()
  await expect(page.getByText('Shape: Rectangle')).toBeVisible()
})
